mapper.select:
SELECT 
FROM gt_investment_product
WHERE org_id = #{orgId}

    AND product_code LIKE CONCAT('%', #{productCode}, '%')


    AND product_name LIKE CONCAT('%', #{productName}, '%')


    AND product_type = #{productType}


    AND issuer LIKE CONCAT('%', #{issuer}, '%')


    AND product_status = #{productStatus}

ORDER BY create_time DESC

SELECT 
FROM gt_investment_product
WHERE product_code = #{productCode} AND org_id = #{orgId}

SELECT COUNT(*)
FROM gt_investment_product
WHERE product_code = #{productCode} AND org_id = #{orgId}

    AND product_id != #{excludeId}

SELECT product_id, product_code, product_name, 'NEAR_MATURITY' as alertType, '产品即将到期' as alertMessage, maturity_date as alertDate FROM gt_investment_product WHERE product_status = 'ACTIVE' AND maturity_date BETWEEN CURDATE() AND DATE_ADD(CURDATE(), INTERVAL 30 DAY) AND org_id = #{orgId}
UNION ALL
SELECT product_id, product_code, product_name, 'SUBSCRIPTION_ENDING' as alertType, '申购期即将结束' as alertMessage, subscription_end_date as alertDate FROM gt_investment_product WHERE product_status = 'ACTIVE' AND subscription_end_date BETWEEN CURDATE() AND DATE_ADD(CURDATE(), INTERVAL 7 DAY) AND org_id = #{orgId}
